"""Editorial visual states. Source pages and speech remain in the approved scripts."""

def panel(title,kind='steps',**kw):return dict(title=title,kind=kind,**kw)
def steps(title,*rows):return panel(title,rows=list(rows))
def table(title,headers,rows):return panel(title,'table',headers=headers,rows=rows)
def formula(title,*rows):return panel(title,'formula',rows=list(rows))
def flow(title,*nodes):return panel(title,'flow',nodes=list(nodes))
def source(page,title):return panel(title,'source',page=page)
def bits(title,rows):return panel(title,'bits',rows=rows)

